package com.wayrapass.service;
import com.wayrapass.dto.request.OperationalRequests;import com.wayrapass.dto.response.OperationalResponses;import com.wayrapass.exception.*;import com.wayrapass.model.*;import com.wayrapass.repository.*;import com.wayrapass.security.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class OperationalService{
 private static final ZoneId SERVICE_ZONE=ZoneId.of("America/Lima");
 private static final Map<TripStatus,Set<TripStatus>> VALID_TRANSITIONS=Map.of(TripStatus.SCHEDULED,EnumSet.of(TripStatus.BOARDING,TripStatus.CANCELLED),TripStatus.BOARDING,EnumSet.of(TripStatus.IN_PROGRESS,TripStatus.CANCELLED),TripStatus.IN_PROGRESS,EnumSet.of(TripStatus.COMPLETED,TripStatus.CANCELLED),TripStatus.COMPLETED,EnumSet.noneOf(TripStatus.class),TripStatus.CANCELLED,EnumSet.noneOf(TripStatus.class));
 private static final List<TripStatus> OPERATIONAL_STATUSES=List.of(TripStatus.BOARDING,TripStatus.IN_PROGRESS);
 private final CurrentUser current;private final TripRepository trips;private final RouteRepository routes;private final RouteScheduleRepository schedules;private final DriverRepository drivers;private final VehicleRepository vehicles;private final StudentRepository students;private final StopRepository stops;private final RouteStopRepository routeStops;private final StudentRouteEnrollmentRepository enrollments;private final BoardingRepository boardings;private final IncidentRepository incidents;private final TripLocationRepository locations;private final NotificationRepository notifications;private final StudentFamilyLinkRepository links;private final UserRepository users;private final AiActionRequestRepository aiRequests;private final StudentAccessService studentAccess;private final EnrollmentLifecycleService enrollmentLifecycle;
 @Transactional(readOnly=true) public List<OperationalResponses.Trip> allTrips(){return trips.findAll().stream().map(this::out).toList();}
 @Transactional(readOnly=true) public List<OperationalResponses.DriverTrip> myDriverTrips(){return myDriverTrips(null,null);}
 @Transactional(readOnly=true) public List<OperationalResponses.DriverTrip> myDriverTrips(LocalDate from,LocalDate to){if(from!=null&&to!=null&&from.isAfter(to))throw new BusinessRuleException("La fecha inicial no puede ser posterior a la fecha final.");Instant fromInstant=from==null?null:from.atStartOfDay(SERVICE_ZONE).toInstant();Instant toExclusive=to==null?null:to.plusDays(1).atStartOfDay(SERVICE_ZONE).toInstant();return trips.findByDriverUserId(current.id()).stream().filter(t->fromInstant==null||!t.getScheduledStartAt().isBefore(fromInstant)).filter(t->toExclusive==null||t.getScheduledStartAt().isBefore(toExclusive)).sorted(Comparator.comparing(Trip::getScheduledStartAt)).map(this::driverTripOut).toList();}
 @Transactional public OperationalResponses.Trip createTrip(OperationalRequests.Trip r){if(!r.scheduledEndAt().isAfter(r.scheduledStartAt()))throw new BusinessRuleException("scheduledEndAt debe ser posterior al inicio.");Route route=routes.findById(r.routeId()).orElseThrow(()->new ResourceNotFoundException("Ruta no encontrada."));if(route.getStatus()!=RouteStatus.ACTIVE)throw new BusinessRuleException("La ruta no está disponible para programación.");Trip t=new Trip();t.setRoute(route);if(r.routeScheduleId()!=null){RouteSchedule sc=schedules.findById(r.routeScheduleId()).orElseThrow(()->new ResourceNotFoundException("Horario no encontrado."));if(!sc.getRoute().getId().equals(r.routeId()))throw new BusinessRuleException("El horario no pertenece a la ruta.");if(!sc.isActive())throw new BusinessRuleException("El horario seleccionado no está activo.");t.setRouteSchedule(sc);}t.setScheduledStartAt(r.scheduledStartAt());t.setScheduledEndAt(r.scheduledEndAt());assign(t,r.driverId(),r.vehicleId(),0L);return out(trips.save(t));}
 @Transactional public OperationalResponses.Trip assignResources(Long tripId,OperationalRequests.Assignment r){Trip t=trips.findByIdForUpdate(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getStatus()!=TripStatus.SCHEDULED)throw new BusinessRuleException("Solo se pueden asignar recursos a un viaje programado.");if(t.getRoute().getStatus()!=RouteStatus.ACTIVE)throw new BusinessRuleException("La ruta no está disponible para asignación.");if(t.getDriver()!=null||t.getVehicle()!=null)throw new ConflictException("El viaje ya tiene recursos asignados; utilice la reasignación.");assign(t,r.driverId(),r.vehicleId(),t.getId());return out(t);}
 @Transactional public OperationalResponses.Trip reassign(Long tripId,OperationalRequests.Reassignment r){if(r.driverId()==null&&r.vehicleId()==null)throw new BusinessRuleException("Debe indicar al menos un conductor o vehículo para la reasignación.");Trip t=trips.findByIdForUpdate(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getStatus()==TripStatus.COMPLETED||t.getStatus()==TripStatus.CANCELLED)throw new BusinessRuleException("No se pueden reasignar recursos en un viaje finalizado o cancelado.");boolean driverChanged=r.driverId()!=null&&(t.getDriver()==null||!r.driverId().equals(t.getDriver().getId()));boolean vehicleChanged=r.vehicleId()!=null&&(t.getVehicle()==null||!r.vehicleId().equals(t.getVehicle().getId()));if(!driverChanged&&!vehicleChanged)throw new BusinessRuleException("La reasignación no modifica los recursos del viaje.");Vehicle previousVehicle=t.getVehicle();assign(t,driverChanged?r.driverId():null,vehicleChanged?r.vehicleId():null,t.getId());if(vehicleChanged&&OPERATIONAL_STATUSES.contains(t.getStatus())){t.getVehicle().setOperationalStatus(VehicleOperationalStatus.IN_SERVICE);releaseVehicle(previousVehicle,t.getId());}t.setWasReassigned(true);if(vehicleChanged)notifyRoute(t,NotificationType.VEHICLE_CHANGE,"Cambio de unidad","Se actualizó la unidad asignada al viaje.",null);if(driverChanged)notifyRoute(t,NotificationType.DRIVER_CHANGE,"Cambio de conductor","Se actualizó el conductor asignado al viaje.",null);if(t.getDriver()!=null)notify(t.getDriver().getUser(),t,vehicleChanged?NotificationType.VEHICLE_CHANGE:NotificationType.GENERAL,"Asignación actualizada","Se actualizó la ruta o unidad de uno de tus recorridos asignados.",null);return out(t);}
 @Transactional(readOnly=true) public OperationalResponses.ReassignmentOptions reassignmentOptions(Long tripId){Trip t=trips.findById(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getStatus()==TripStatus.COMPLETED||t.getStatus()==TripStatus.CANCELLED)throw new BusinessRuleException("No se pueden consultar alternativas para un viaje finalizado o cancelado.");List<OperationalResponses.DriverOption> driverOptions=drivers.findAllByOrderByIdAsc().stream().filter(d->t.getDriver()==null||!d.getId().equals(t.getDriver().getId())).filter(this::eligibleDriver).filter(d->!trips.driverOverlaps(d.getId(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getId())).map(this::driverOption).toList();List<OperationalResponses.VehicleOption> vehicleOptions=vehicles.findAllByOrderByIdAsc().stream().filter(v->t.getVehicle()==null||!v.getId().equals(t.getVehicle().getId())).filter(this::eligibleVehicle).filter(v->!trips.vehicleOverlaps(v.getId(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getId())).map(this::vehicleOption).toList();String message=driverOptions.isEmpty()&&vehicleOptions.isEmpty()?"No existen recursos disponibles para realizar la reasignación":null;return new OperationalResponses.ReassignmentOptions(t.getId(),driverOptions,vehicleOptions,message);}
 @Transactional(readOnly=true) public List<OperationalResponses.WeeklyOperation> weeklyCalendar(LocalDate from,LocalDate to){if(from.isAfter(to)||from.getDayOfWeek()!=DayOfWeek.MONDAY||to.getDayOfWeek()!=DayOfWeek.SUNDAY||to.toEpochDay()-from.toEpochDay()!=6)throw new BusinessRuleException("El calendario debe consultarse de lunes a domingo dentro de una misma semana.");Instant start=from.atStartOfDay(SERVICE_ZONE).toInstant();Instant endExclusive=to.plusDays(1).atStartOfDay(SERVICE_ZONE).toInstant();return trips.findCalendarOperations(start,endExclusive).stream().map(this::weeklyOperationOut).toList();}
 @Transactional public OperationalResponses.Trip status(Long tripId,TripStatus status){Trip t=trips.findByIdForUpdate(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));User u=current.require();if(u.getRole()!=Role.COORDINATOR&&(t.getDriver()==null||!t.getDriver().getUser().getId().equals(u.getId())))throw new AccessDeniedException("Sin acceso al viaje.");if(!VALID_TRANSITIONS.getOrDefault(t.getStatus(),Set.of()).contains(status))throw new BusinessRuleException("Transición de estado no permitida: "+t.getStatus()+" -> "+status+".");if(status==TripStatus.BOARDING)activateResources(t);if(status==TripStatus.IN_PROGRESS&&t.getActualStartAt()==null)t.setActualStartAt(Instant.now());if(status==TripStatus.COMPLETED){t.setActualEndAt(Instant.now());releaseVehicle(t.getVehicle(),t.getId());}if(status==TripStatus.CANCELLED)releaseVehicle(t.getVehicle(),t.getId());t.setStatus(status);if(status==TripStatus.COMPLETED)notifyRoute(t,NotificationType.ARRIVAL,"Llegada confirmada","El viaje llegó a su destino.",null);return out(t);}
 private void assign(Trip t,Long driverId,Long vehicleId,Long exclude){if(driverId!=null){Driver d=drivers.findByIdForUpdate(driverId).orElseThrow(()->new ResourceNotFoundException("Conductor no encontrado."));if(!eligibleDriver(d))throw new BusinessRuleException("El conductor no está autorizado, habilitado y con licencia vigente.");if(trips.driverOverlaps(driverId,t.getScheduledStartAt(),t.getScheduledEndAt(),exclude))throw new ConflictException("El recurso seleccionado no se encuentra disponible");t.setDriver(d);}if(vehicleId!=null){Vehicle v=vehicles.findByIdForUpdate(vehicleId).orElseThrow(()->new ResourceNotFoundException("Vehículo no encontrado."));if(!eligibleVehicle(v))throw new BusinessRuleException("El vehículo no está autorizado y disponible.");if(trips.vehicleOverlaps(vehicleId,t.getScheduledStartAt(),t.getScheduledEndAt(),exclude))throw new ConflictException("El recurso seleccionado no se encuentra disponible");t.setVehicle(v);}}
 private boolean eligibleDriver(Driver d){return d.getAuthorizationStatus()==AuthorizationStatus.AUTHORIZED&&d.getOperationalStatus()==DriverOperationalStatus.AVAILABLE&&d.getUser().isEnabled()&&d.getLicenseExpiration()!=null&&!d.getLicenseExpiration().isBefore(LocalDate.now(SERVICE_ZONE));}
 private boolean eligibleVehicle(Vehicle v){return v.getAuthorizationStatus()==AuthorizationStatus.AUTHORIZED&&v.getOperationalStatus()==VehicleOperationalStatus.AVAILABLE;}
 @Transactional public OperationalResponses.Location location(Long tripId,OperationalRequests.Location r){Trip t=ownedTrip(tripId);if(t.getStatus()!=TripStatus.BOARDING&&t.getStatus()!=TripStatus.IN_PROGRESS)throw new BusinessRuleException("Solo se registra ubicación durante un viaje activo.");TripLocation l=new TripLocation();l.setTrip(t);l.setLatitude(r.latitude());l.setLongitude(r.longitude());return out(locations.save(l));}
 @Transactional(readOnly=true) public OperationalResponses.Location latestLocation(Long tripId){Trip t=trips.findById(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));studentAccess.requireTripAccess(t);return out(locations.findFirstByTripIdOrderByRecordedAtDesc(tripId).orElseThrow(()->new ResourceNotFoundException("El viaje aún no tiene ubicaciones.")));}
 @Transactional public OperationalResponses.Boarding board(OperationalRequests.Boarding r){User u=current.require();Student s=students.findByUserId(u.getId()).orElseThrow(()->new AccessDeniedException("Solo estudiantes."));Trip t=trips.findByIdForUpdate(r.tripId()).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getVehicle()==null||!t.getVehicle().getQrToken().equals(r.vehicleQrToken()))throw new BusinessRuleException("El QR no corresponde al vehículo asignado.");if(t.getStatus()!=TripStatus.BOARDING&&t.getStatus()!=TripStatus.IN_PROGRESS)throw new BusinessRuleException("El viaje no admite abordaje.");StudentRouteEnrollment e=enrollmentLifecycle.currentForUse(s.getId()).filter(x->x.getRoute().getId().equals(t.getRoute().getId())).orElseThrow(()->new BusinessRuleException("El estudiante no pertenece a este viaje."));if(e.getStatus()!=EnrollmentStatus.ACTIVE)throw new BusinessRuleException("La inscripción del estudiante está suspendida.");if(!e.getStop().getId().equals(r.stopId())||!routeStops.existsByRouteIdAndStopId(t.getRoute().getId(),r.stopId()))throw new BusinessRuleException("El paradero no corresponde a la inscripción.");if(boardings.existsByTripIdAndStudentId(t.getId(),s.getId()))throw new ConflictException("El estudiante ya abordó este viaje.");Boarding b=new Boarding();b.setTrip(t);b.setStudent(s);b.setStop(stops.findById(r.stopId()).orElseThrow(()->new ResourceNotFoundException("Paradero no encontrado.")));boardings.save(b);links.findByStudentIdAndAuthorizedTrue(s.getId()).stream().filter(StudentFamilyLink::isNotifyBoarding).forEach(l->notify(l.getFamilyUser(),t,NotificationType.BOARDING,"Abordaje confirmado",s.getUser().getFullName()+" abordó el vehículo.",null));return out(b);}
 @Transactional public OperationalResponses.Incident incident(OperationalRequests.Incident r){Trip t=ownedTrip(r.tripId());if(!OPERATIONAL_STATUSES.contains(t.getStatus()))throw new BusinessRuleException("Solo se pueden registrar incidencias durante el abordaje o un viaje en curso.");Incident i=new Incident();i.setTrip(t);i.setDriver(t.getDriver());i.setType(r.type());i.setDescription(r.description());i.setDelayMinutes(r.delayMinutes());i.setPriority(r.type()==IncidentType.VEHICLE_FAILURE&&r.priority()==IncidentPriority.NORMAL?IncidentPriority.HIGH:r.priority());incidents.save(i);if(r.delayMinutes()>0){Instant base=t.getEstimatedArrivalAt()!=null?t.getEstimatedArrivalAt():t.getScheduledEndAt();if(base!=null)t.setEstimatedArrivalAt(base.plusSeconds(r.delayMinutes()*60L));}NotificationType notificationType=r.delayMinutes()>0?NotificationType.DELAY:NotificationType.INCIDENT;String message=r.description()==null||r.description().isBlank()?r.type().name():r.description();notifyRoute(t,notificationType,"Incidencia reportada",message,i);for(User coordinator:users.findByRoleAndEnabledTrue(Role.COORDINATOR))notify(coordinator,t,NotificationType.INCIDENT,"Incidencia de recorrido",message,i);return out(i);}
 @Transactional(readOnly=true) public List<OperationalResponses.Notification> myNotifications(){return notifications.findByRecipientIdOrderByCreatedAtDesc(current.id()).stream().map(this::out).toList();}
 @Transactional public OperationalResponses.AiAction propose(OperationalRequests.AiProposal r){if(r.proposedDriverId()==null&&r.proposedVehicleId()==null)throw new BusinessRuleException("Debe proponerse al menos un recurso.");AiActionRequest a=new AiActionRequest();a.setRequestedBy(current.require());a.setTrip(trips.findById(r.tripId()).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado.")));a.setActionType(r.actionType());if(r.proposedDriverId()!=null)a.setProposedDriver(drivers.findById(r.proposedDriverId()).orElseThrow(()->new ResourceNotFoundException("Conductor no encontrado.")));if(r.proposedVehicleId()!=null)a.setProposedVehicle(vehicles.findById(r.proposedVehicleId()).orElseThrow(()->new ResourceNotFoundException("Vehículo no encontrado.")));a.setRequestText(r.requestText());a.setAiExplanation(r.aiExplanation());return out(aiRequests.save(a));}
 @Transactional public OperationalResponses.AiAction confirm(Long id){AiActionRequest a=aiRequests.findById(id).orElseThrow(()->new ResourceNotFoundException("Solicitud IA no encontrada."));if(a.getStatus()!=AiActionStatus.PENDING)throw new ConflictException("La solicitud ya fue procesada.");a.setConfirmedBy(current.require());a.setConfirmedAt(Instant.now());a.setStatus(AiActionStatus.CONFIRMED);reassign(a.getTrip().getId(),new OperationalRequests.Reassignment(a.getProposedDriver()==null?null:a.getProposedDriver().getId(),a.getProposedVehicle()==null?null:a.getProposedVehicle().getId()));a.setExecutedAt(Instant.now());a.setStatus(AiActionStatus.EXECUTED);return out(a);}
 private Trip ownedTrip(Long id){Trip t=trips.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getDriver()==null||!t.getDriver().getUser().getId().equals(current.id()))throw new AccessDeniedException("El viaje no está asignado al conductor autenticado.");return t;}
 private void activateResources(Trip t){if(t.getDriver()!=null&&!eligibleDriver(t.getDriver()))throw new BusinessRuleException("El conductor no está autorizado, habilitado y con licencia vigente.");if(t.getVehicle()!=null){if(!eligibleVehicle(t.getVehicle()))throw new BusinessRuleException("El vehículo no está autorizado y disponible.");t.getVehicle().setOperationalStatus(VehicleOperationalStatus.IN_SERVICE);}}
 private void releaseVehicle(Vehicle vehicle,Long tripId){if(vehicle!=null&&vehicle.getOperationalStatus()==VehicleOperationalStatus.IN_SERVICE&&!trips.existsByVehicleIdAndStatusInAndIdNot(vehicle.getId(),OPERATIONAL_STATUSES,tripId))vehicle.setOperationalStatus(VehicleOperationalStatus.AVAILABLE);}
 private void notifyRoute(Trip t,NotificationType type,String title,String message,Incident i){for(StudentRouteEnrollment e:enrollments.findByRouteIdAndStatus(t.getRoute().getId(),EnrollmentStatus.ACTIVE)){notify(e.getStudent().getUser(),t,type,title,message,i);for(StudentFamilyLink l:links.findByStudentIdAndAuthorizedTrue(e.getStudent().getId()))if(wantsNotification(l,type))notify(l.getFamilyUser(),t,type,title,message,i);}}
 private boolean wantsNotification(StudentFamilyLink l,NotificationType type){return switch(type){case BOARDING->l.isNotifyBoarding();case ARRIVAL->l.isNotifyArrival();case DELAY->l.isNotifyDelay();case VEHICLE_CHANGE,DRIVER_CHANGE->l.isNotifyVehicleChange();case INCIDENT->l.isNotifyIncident();default->true;};}
 private void notify(User u,Trip t,NotificationType type,String title,String message,Incident i){Notification n=new Notification();n.setRecipient(u);n.setTrip(t);n.setIncident(i);n.setType(type);n.setTitle(title);n.setMessage(message);notifications.save(n);}
 private OperationalResponses.Trip out(Trip t){return new OperationalResponses.Trip(t.getId(),t.getRoute().getId(),t.getDriver()==null?null:t.getDriver().getId(),t.getVehicle()==null?null:t.getVehicle().getId(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getEstimatedArrivalAt(),t.getStatus(),t.isWasReassigned());}
 private OperationalResponses.DriverTrip driverTripOut(Trip t){Route r=t.getRoute();OperationalResponses.DriverVehicle vehicle=t.getVehicle()==null?null:new OperationalResponses.DriverVehicle(t.getVehicle().getId(),t.getVehicle().getPlate(),t.getVehicle().getBrand(),t.getVehicle().getModel(),t.getVehicle().getCapacity());List<OperationalResponses.DriverRouteStop> stops=routeStops.findByRouteIdOrderByStopOrder(r.getId()).stream().map(rs->new OperationalResponses.DriverRouteStop(rs.getStop().getId(),rs.getStopOrder(),rs.getStop().getName(),rs.getStop().getAddress(),rs.getStop().getDistrict(),rs.getEstimatedMinutesFromStart(),rs.isActive()&&rs.getStop().isActive())).toList();return new OperationalResponses.DriverTrip(t.getId(),t.getId(),r.getId(),t.getDriver()==null?null:t.getDriver().getId(),t.getVehicle()==null?null:t.getVehicle().getId(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getEstimatedArrivalAt(),t.getStatus(),t.isWasReassigned(),r.getCode(),r.getName(),r.getOrigin(),r.getDestination(),t.getRouteSchedule()==null?null:t.getRouteSchedule().getId(),t.getActualStartAt(),t.getActualEndAt(),t.isWasReassigned(),t.isWasReassigned()?"La asignación de este recorrido fue actualizada.":null,vehicle,stops);}
 private OperationalResponses.DriverOption driverOption(Driver d){return new OperationalResponses.DriverOption(d.getId(),d.getUser().getFullName(),d.getLicenseNumber(),d.getLicenseCategory(),d.getLicenseExpiration(),d.getAuthorizationStatus(),d.getOperationalStatus());}
 private OperationalResponses.VehicleOption vehicleOption(Vehicle v){return new OperationalResponses.VehicleOption(v.getId(),v.getPlate(),v.getBrand(),v.getModel(),v.getCapacity(),v.getAuthorizationStatus(),v.getOperationalStatus());}
 private OperationalResponses.WeeklyOperation weeklyOperationOut(Trip t){Route r=t.getRoute();return new OperationalResponses.WeeklyOperation(t.getId(),t.getScheduledStartAt().atZone(SERVICE_ZONE).toLocalDate(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getStatus(),r.getId(),r.getCode(),r.getName(),r.getOrigin(),r.getDestination(),t.getDriver()==null?null:driverOption(t.getDriver()),t.getVehicle()==null?null:vehicleOption(t.getVehicle()),t.isWasReassigned(),t.isWasReassigned()?"La operación fue modificada o reasignada.":null);}
 private OperationalResponses.Location out(TripLocation l){return new OperationalResponses.Location(l.getId(),l.getTrip().getId(),l.getLatitude(),l.getLongitude(),l.getRecordedAt());}private OperationalResponses.Boarding out(Boarding b){return new OperationalResponses.Boarding(b.getId(),b.getTrip().getId(),b.getStudent().getId(),b.getStop().getId(),b.getBoardedAt());}private OperationalResponses.Incident out(Incident i){return new OperationalResponses.Incident(i.getId(),i.getTrip().getId(),i.getTrip().getRoute().getId(),i.getDriver().getId(),i.getType(),i.getDescription(),i.getDelayMinutes(),i.getPriority(),i.getStatus(),i.getCreatedAt());}private OperationalResponses.Notification out(Notification n){return new OperationalResponses.Notification(n.getId(),n.getType(),n.getTitle(),n.getMessage(),n.getCreatedAt(),n.getReadAt());}private OperationalResponses.AiAction out(AiActionRequest a){return new OperationalResponses.AiAction(a.getId(),a.getTrip().getId(),a.getActionType(),a.getStatus(),a.getProposedDriver()==null?null:a.getProposedDriver().getId(),a.getProposedVehicle()==null?null:a.getProposedVehicle().getId());}
}
